#include <string>
#include <sstream>
#include <iostream>

class Memory;

class Parser {
public:
    static unsigned parse_hex(const std::string &hex) {
        return strtol(hex.c_str(), nullptr, 16);
    }

    static void parse(std::istream &in, Memory &mem) {
        if (!in.good()) {
            std::cerr << "Error: Invalid input stream" << std::endl;
            return;
        }

        unsigned base = 0;
        std::string line;

        while (std::getline(in, line)) {
            if (line.empty()) continue;

            if (line[0] == '@') {
                std::string addr_str = line.substr(1);
                base = parse_hex(addr_str);
            } else {
                std::istringstream iss(line);
                std::string token;
                while (iss >> token) {
                    unsigned value = parse_hex(token);
                    mem.write_byte(base, static_cast<unsigned char>(value));
                    base++;
                }
            }
        }
    }

    static void parse_hex(std::istream &in, Memory &mem) {
        if (!in.good()) {
            std::cerr << "Error: Invalid input stream" << std::endl;
            return;
        }

        unsigned base = 0;
        std::string line;

        while (std::getline(in, line)) {
            if (line.empty()) continue;

            std::istringstream iss(line);
            std::string token;
            while (iss >> token) {
                unsigned value = parse_hex(token);
                mem.write_word(base, value);
                base += 4;
            }
        }
    }
};
